class cuckoo(BotPlugin):

    @botcmd(split_args_with=None, hidden=True)
    def cuckoo(self, msg, args):
        if not len(args)>=1:
            return("Incorrect number of parameters.  Syntax:  !cuckoo -<s | u <Defanged_URL> | vt <hash> | v <task_id> | r <task_id>>\r\n!cuckoo -s (provides Cuckoo status)\r\n!cuckoo -u <Defanged_URL> (runs a URL - [.] and (.) accepted)\r\n!cuckoo -vt <hash> (downloads a file from VT and runs the file\r\n!cuckoo -v <task_id> (views stats of task)\r\n!cuckoo -r <task_id> (views report for task)")
            exit()

        if server=="changeme":
            return("Error:  Cuckoo server not configured in script.  This plugin will not work until fixed.")

        # Assign arguments to variables 
        function=args[0]

        # Check function
        fvalid = re.match(r'^-s$', function) or re.match(r'^-u$', function) or re.match(r'^-vt$', function) or re.match(r'^-v$', function) or re.match(r'^-r$', function)
        if not fvalid:
            return("Incorrect function.  Syntax:  !cuckoo -<s | u <Defanged_URL> | vt <hash> | v <task_id> | r task_id>>\r\n!cuckoo -s (provides Cuckoo status)\r\n!cuckoo -u <Defanged_URL> (runs a URL - [.] and (.) accepted)\r\n!cuckoo -vt <hash> (downloads a file from VT and runs the file\r\n!cuckoo -v <task_id> (views a task)\r\n!cuckoo -r <task_id> (views report for task)")
            exit()

        results="Querying Cuckoo Server: " + server + ":" + port

        ##################  STATUS QUERY  ################## 
        if re.match(r'^-s$', function):
            results=cuckoo_status(results)

        ##################  URL QUERY  ################## 
        elif re.match(r'^-u$', function):
            results=cuckoo_url(results, args)

        ##################  FILE QUERY  ################## 
        elif re.match(r'^-vt$', function):
            if vtapikey=="changeme":
                return("Error:  Private VirusTotal API Key not configured in script.  This function will not work until fixed.")
            else:
                results=cuckoo_file(results, args)

        ##################  VIEW QUERY  ################## 
        elif re.match(r'^-v$', function):
            results=cuckoo_view(results, args)

        ##################  REPORT QUERY  ################## 
        elif re.match(r'^-r$', function):
            results=cuckoo_report(results, args)

        else:
            return("No Function Match.")
            exit()

        return(results)

from pymonad.either import Either as __pyEither
from typing import Any, Generic, TypeVar


"""
# Aided with basic GitHub coding tools

This module extends the functionality of the `pymonad.either.Either` class by adding additional
methods and shorthand operators for improved usability.

Classes:
    Either: A subclass of `pymonad.either.Either` that provides additional methods and operator overloads.

Functions:
    Left(value: M) -> Either[M, Any]:
        Creates a value of the first possible type in the Either monad, representing a failure or error state.

    Right(value: T) -> Either[Any, T]:
        Creates a value of the second possible type in the Either monad, representing a success state.

Type Variables:
    M: Represents the type of the value in the `Left` state (typically used for error messages or failure values).
    S: Unused in this module but reserved for potential future extensions.
    T: Represents the type of the value in the `Right` state (typically used for success values).
"""


M = TypeVar('M')
S = TypeVar('S')
T = TypeVar('T')


class Either(__pyEither, Generic[M, T]):
    """Extend pymonad Either"""

    def __rshift__(self, func):
        """Use `>>` as a shorthand for `bind`"""
        return self.bind(func)

    def __or__(self, func):
        """Use `|` as a shorthand for `bind`"""
        return self.bind(func)

    def then(self, func):
        """Use `then` as a shorthand for `bind`"""
        return self.bind(func)

    @property
    def error(self) :
        """when the instance is a Left, can use `l.error` to get the error message"""
        if self.is_left():
            return self.monoid[0]
        return None


def Left(value) :
    """Creates a value of the first possible type in the Either monad."""
    return Either(None, (value, False))


def Right(value) :
    """Creates a value of the second possible type in the Either monad."""
    return Either(value, (None, True))

import torch
import torch.nn as nn
from torch.autograd.function import Function
from torch.utils.checkpoint import get_device_states, set_device_states

# helpers

def sum_tuple(x, y, dim = 1):
    x = list(x)
    x[dim] += y[dim]
    return tuple(x)

def subtract_tuple(x, y, dim = 1):
    x = list(x)
    x[dim] -= y[dim]
    return tuple(x)

def set_tuple(x, dim, value):
    x = list(x).copy()
    x[dim] = value
    return tuple(x)

def map_tuple(fn, x, dim = 1):
    x = list(x)
    x[dim] = fn(x[dim])
    return tuple(x)

def chunk_tuple(fn, x, dim = 1):
    x = list(x)
    value = x[dim]
    chunks = fn(value)
    return tuple(map(lambda t: set_tuple(x, 1, t), chunks))

def cat_tuple(x, y, dim = 1, cat_dim = -1):
    x = list(x)
    y = list(y)
    x[dim] = torch.cat((x[dim], y[dim]), dim = cat_dim)
    return tuple(x)

def del_tuple(x):
    for el in x:
        if el is not None:
            del el

# following example for saving and setting rng here https://pytorch.org/docs/stable/_modules/torch/utils/checkpoint.html
class Deterministic(nn.Module):
    def __init__(self, net):
        super().__init__()
        self.net = net
        self.cpu_state = None
        self.cuda_in_fwd = None
        self.gpu_devices = None
        self.gpu_states = None

    def record_rng(self, *args):
        self.cpu_state = torch.get_rng_state()
        if torch.cuda._initialized:
            self.cuda_in_fwd = True
            self.gpu_devices, self.gpu_states = get_device_states(*args)

    def forward(self, *args, record_rng = False, set_rng = False, **kwargs):
        if record_rng:
            self.record_rng(*args)

        if not set_rng:
            return self.net(*args, **kwargs)

        rng_devices = []
        if self.cuda_in_fwd:
            rng_devices = self.gpu_devices

        with torch.random.fork_rng(devices=rng_devices, enabled=True):
            torch.set_rng_state(self.cpu_state)
            if self.cuda_in_fwd:
                set_device_states(self.gpu_devices, self.gpu_states)
            return self.net(*args, **kwargs)

# heavily inspired by https://github.com/RobinBruegger/RevTorch/blob/master/revtorch/revtorch.py
# once multi-GPU is confirmed working, refactor and send PR back to source
class ReversibleBlock(nn.Module):
    def __init__(self, f, g):
        super().__init__()
        self.f = Deterministic(f)
        self.g = Deterministic(g)

    def forward(self, x, f_args = {}, g_args = {}):
        training = self.training
        x1, x2 = chunk_tuple(lambda t: torch.chunk(t, 2, dim=2), x)
        y1, y2 = None, None

        with torch.no_grad():
            y1 = sum_tuple(self.f(x2, record_rng = training, **f_args), x1)
            y2 = sum_tuple(self.g(y1, record_rng = training, **g_args), x2)

        return cat_tuple(y1, y2, cat_dim = 2)

    def backward_pass(self, y, dy, f_args = {}, g_args = {}):
        y1, y2 = chunk_tuple(lambda t: torch.chunk(t, 2, dim=2), y)
        del_tuple(y)

        dy1, dy2 = torch.chunk(dy, 2, dim=2)
        del dy

        with torch.enable_grad():
            y1[1].requires_grad = True
            gy1 = self.g(y1, set_rng=True, **g_args)
            torch.autograd.backward(gy1[1], dy2)

        with torch.no_grad():
            x2 = subtract_tuple(y2, gy1)
            del_tuple(y2)
            del gy1

            dx1 = dy1 + y1[1].grad
            del dy1
            y1[1].grad = None

        with torch.enable_grad():
            x2[1].requires_grad = True
            fx2 = self.f(x2, set_rng = True, **f_args)
            torch.autograd.backward(fx2[1], dx1)

        with torch.no_grad():
            x1 = subtract_tuple(y1, fx2)
            del fx2
            del_tuple(y1)

            dx2 = dy2 + x2[1].grad
            del dy2
            x2[1].grad = None

            x2 = map_tuple(lambda t: t.detach(), x2)
            x = cat_tuple(x1, x2, cat_dim = -1)
            dx = torch.cat((dx1, dx2), dim=2)

        return x, dx

class _ReversibleFunction(Function):
    @staticmethod
    def forward(ctx, x, blocks, kwargs):
        ctx.kwargs = kwargs
        x = (kwargs.pop('coords'), x, kwargs.pop('mask'), kwargs.pop('edges'))

        for block in blocks:
            x = block(x, **kwargs)

        ctx.y = map_tuple(lambda t: t.detach(), x, dim = 1)
        ctx.blocks = blocks        
        return x[1]

    @staticmethod
    def backward(ctx, dy):
        y = ctx.y
        kwargs = ctx.kwargs

        for block in ctx.blocks[::-1]:
            y, dy = block.backward_pass(y, dy, **kwargs)
        return dy, None, None

class SequentialSequence(nn.Module):
    def __init__(self, blocks):
        super().__init__()
        self.blocks = blocks

    def forward(self, x):
        for (f, g) in self.blocks:
            x = sum_tuple(f(x), x, dim = 1)
            x = sum_tuple(g(x), x, dim = 1)
        return x

class ReversibleSequence(nn.Module):
    def __init__(self, blocks):
        super().__init__()
        self.blocks = nn.ModuleList([ReversibleBlock(f, g) for (f, g) in blocks])

    def forward(self, x, **kwargs):
        x = map_tuple(lambda t: torch.cat((t, t), dim = -1), x)

        blocks = self.blocks

        coords, values, mask, edges = x
        kwargs = {'coords': coords, 'mask': mask, 'edges': edges, **kwargs}
        x = _ReversibleFunction.apply(values, blocks, kwargs)

        x = (coords, x, mask, edges)
        return map_tuple(lambda t: sum(t.chunk(2, dim = -1)) * 0.5, x)

